var i=[{title:`Stresul tău total`,text:`Antrenamentul este doar o parte din stresul pe care îl porți. Somnul slab, călătoriile, o slujbă solicitantă, încordarea emoțională, căldura și o boală recentă pot afecta concentrarea, coordonarea și cât de grea pare munca. Pregătirea nu este un diagnostic și niciun scor singur nu o cuprinde.`},{title:`O verificare simplă`,text:`Înainte de un antrenament, observă-ți somnul, energia, motivația, durerea musculară și orice simptome noi. Compară-le cu ce este normal pentru tine, nu cu cifrele altcuiva. Încălzirea îți oferă o a doua verificare: dacă mișcările par neașteptat de grele sau controlul ți-e dereglat, o sesiune solicitantă poate necesita ajustări.`},{title:`Ajustarea într-o zi slabă`,text:`Într-o zi cu energie scăzută, scade sarcina, scurtează sesiunea, alege exerciții mai simple sau ieși la o plimbare ușoară. Într-o zi normală, fă planul așa cum este scris. Nu transforma fiecare scădere scurtă într-o zi de odihnă. Tendințele pe mai multe sesiuni îți spun mai mult decât o singură evaluare.`},{title:`Boala și siguranța`,text:`Febra, boala care afectează tot corpul, simptomele la piept sau lipsa neobișnuită de aer sunt motive să renunți la antrenamentul greu și să ceri sfat medical. Popularul „test al gâtului” este doar o regulă aproximativă și nu îți dă undă verde pentru exercițiu cât ești bolnav.`},{title:`Folosirea TrainUp`,text:`TrainUp nu prescrie greutăți, așa că alegi sarcina în fiecare zi. Planul tău se schimbă doar când îl regenerezi, pe baza efortului (RPE) pe care l-ai evaluat după fiecare sesiune, a oricărei dureri raportate și a cât ai terminat din fiecare antrenament.`}];var r=[{label:`CDC: recomandări de somn`,url:`https://www.cdc.gov/sleep/about/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: durerea în piept și simptomele de urgență`,url:`https://www.nhs.uk/symptoms/chest-pain/`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};